 Biển, xã Thuận Hòa cũ, huyện An Minh (QWJ3+7GX)","category":"nha_sach","phone":"0948304019","tax_code":null,"source_key":"gmap:ChIJ4Uvd1DsxpzER8Pf5vsicpMU","source_url":"https://www.google.com/maps/search/?api=1&query=H%E1%BA%BFt%20Loan%20%E1%BA%A4p%2010%20Bi%E1%BB%83n%20%E1%BA%A4p%2010%20Bi%E1%BB%83n%2C%20x%C3%A3%20Thu%E1%BA%ADn%20H%C3%B2a%20c%C5%A9%2C%20huy%E1%BB%87n%20An%20Minh%20(QWJ3%2B7GX)%20Ki%C3%AAn%20Giang&query_place_id=ChIJ4Uvd1DsxpzER8Pf5vsicpMU","verification_note":"Nguồn Maps đặt tên theo chủ cửa hàng chứ không rõ biển hiệu nhà sách; phải xác minh ngành hàng thực tế."}]'::jsonb) AS x(district text,name text,address_line text,category text,
 phone text,tax_code text,source_key text,source_url text,verification_note text)),
 ins AS(
 INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Kiên Giang',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; cửa hàng/hoạt động bán lẻ phải xác minh thực địa. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-kien-giang-old-wave-02'
 FROM src s WHERE s.district IN ('Huyện Châu Thành','Huyện Giồng Riềng','Huyện Gò Quao','Huyện An Biên','Huyện An Minh') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.province='Kiên Giang' AND c.district=s.district
 AND (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM public.field_prospects p WHERE p.province='Kiên Giang' AND p.district=s.district
 AND (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores FROM ins GROUP BY district ORDER BY district;